#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {   //@ @layout open:container
    map<string, int> m;   //@ @tts [next] 準備一個空的 map
    m["apple"] = 3;   //@ @guide {m} @tts [next] 放進蘋果，數量三
    m["pear"] = 5;   //@ @guide {m} @tts [next] 放進梨子，數量五
    m["fig"] = 2;   //@ @guide {m} @tts [next] 放進無花果，數量二
    m["apple"] = 4;   //@ @guide {m} @tts [next] 蘋果已經有了，這一行會把它改成四
    cout << m.size() << endl;   //@ @guide {m} @tts [next] 還是三組，因為蘋果只是被改掉
    return 0;   //@ @tts [continue] 程式結束
}
